+fn close_planner_stream_sources(sources: &Rc<RefCell<PlannerStreamSources>>) {
+    let (agent, permission) = {
+        let mut sources = sources.borrow_mut();
+        let agent = sources.agent.take();
+        let permission = sources.permission.take();
+        sources.session_id.clear();
+        sources.generation = 0;
+        sources.lifecycle.reset();
+        (agent, permission)
+    };
+    // gloo-net 0.6 clones share one web_sys::EventSource. `close` wakes the
+    // subscriber stream; doing it after the borrow is released avoids a
+    // re-entrant RefCell borrow through the dispatched close notification.
+    if let Some(agent) = agent {
+        agent.close();
+    }
+    if let Some(permission) = permission {
+        permission.close();
+    }
+}
